{"code":"import pandas as pd, statsmodels.formula.api as smf
D=pd.read_csv('data/explore.csv')
xs=['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']
for x in xs:
 m=smf.ols(f'tensile_mpa ~ {x} + C(lab)',D).fit()
 print(x, 'b',round(m.params[x],3),'p',m.pvalues[x], 'r2',round(m.rsquared,3))"}
